#include <stdio.h>
#include <string.h>

int check_win(char board[6][7], char player) {
    // Horizontal
    for (int r = 0; r < 6; r++)
        for (int c = 0; c < 4; c++)
            if (board[r][c]==player && board[r][c+1]==player &&
                board[r][c+2]==player && board[r][c+3]==player) return 1;
    // Vertical
    for (int r = 0; r < 3; r++)
        for (int c = 0; c < 7; c++)
            if (board[r][c]==player && board[r+1][c]==player &&
                board[r+2][c]==player && board[r+3][c]==player) return 1;
    // Diagonal (\ and /)
    for (int r = 0; r < 3; r++)
        for (int c = 0; c < 4; c++) {
            if (board[r][c]==player && board[r+1][c+1]==player &&
                board[r+2][c+2]==player && board[r+3][c+3]==player) return 1;
            if (board[r][c+3]==player && board[r+1][c+2]==player &&
                board[r+2][c+1]==player && board[r+3][c]==player) return 1;
        }
    return 0;
}

int main() {
    char board[6][7] = {0};
    board[3][0]='X'; board[3][1]='X'; board[3][2]='X'; board[3][3]='X';
    board[0][3]='O';
    printf("X wins: %d\n", check_win(board, 'X'));
    printf("O wins: %d\n", check_win(board, 'O'));
    return 0;
}
